import {
	AfterViewInit,
	ChangeDetectionStrategy,
	ChangeDetectorRef,
	Component,
	ElementRef,
	Inject,
	Input,
	NgZone,
	OnDestroy,
	OnInit,
	PLATFORM_ID,
} from '@angular/core';
import { CommonModule, isPlatformBrowser } from '@angular/common';
import { RouterModule } from '@angular/router';
import { TranslateModule } from '@ngx-translate/core';
import { TranslationService } from '../../../core/services/translation.service';
import { ProjectService } from '../../../providers/project/project.service';
import { environment } from '../../../../environments/environment';

interface TechStackItem {
	key: string;
	label: string;
	icon: string;
}

@Component({
	selector: 'app-recent-work-marquee',
	standalone: true,
	imports: [CommonModule, RouterModule, TranslateModule],
	templateUrl: './recent-work-marquee.component.html',
	styleUrl: './recent-work-marquee.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
})
export class RecentWorkMarqueeComponent implements OnInit, AfterViewInit, OnDestroy {
	@Input() serviceName = 'website';
	@Input() consultationLink = '/contact';
	/** Service key the contact page should pre-select (see ContactComponent.serviceOptions). Defaults to `serviceName`. */
	@Input() contactService = '';
	@Input() showTechStack = true;
	imagePath: string;
	baseUrl: string;

	private readonly isBrowser: boolean;
	private readonly boundThumbs = new WeakSet<HTMLElement>();
	private readonly cardHoverCleanups: Array<() => void> = [];

	readonly techStack: TechStackItem[] = [
		{ key: 'react', label: 'React', icon: '/images/new-images/tools/react.webp' },
		{ key: 'angular', label: 'Angular', icon: '/images/new-images/tools/angular.webp' },
		{ key: 'nodejs', label: 'Node JS', icon: '/images/new-images/tools/nodejs.webp' },
		{ key: 'nextjs', label: 'Next JS', icon: '/images/new-images/tools/nextjs.webp' },
		{ key: 'magento', label: 'Magento', icon: '/images/new-images/tools/magento.webp' },
	];

	marqueeRowTop: any[] = [];
	marqueeRowBottom: any[] = [];

	constructor(
		private projectService: ProjectService,
		public translationService: TranslationService,
		private cdr: ChangeDetectorRef,
		@Inject(PLATFORM_ID) private platformId: Object,
		private readonly hostRef: ElementRef<HTMLElement>,
		private readonly ngZone: NgZone,
	) {
		this.imagePath = environment.baseUrl + '/public/';
		this.baseUrl = environment.url;
		this.isBrowser = isPlatformBrowser(this.platformId);
	}

	ngOnInit(): void {
		this.getRecentWebsites();
	}

	ngAfterViewInit(): void {
		if (!this.isBrowser) {
			return;
		}

		this.ngZone.runOutsideAngular(() => this.setupCardHoverButtons());
	}

	ngOnDestroy(): void {
		this.cardHoverCleanups.forEach((cleanup) => cleanup());
		this.cardHoverCleanups.length = 0;
	}

	get contactServiceKey(): string {
		return (this.contactService || this.serviceName || '').toLowerCase();
	}

	getRecentWebsites(): void {
		const obj = {
			limit: 100,
			page: 1,
		};

		this.projectService.getAllProjects(obj).subscribe((response: any) => {
			if (response.code === 200) {
				const result = response.result ?? response.data ?? [];

				const websiteProjects = result.filter(
					(project: any) =>
						Array.isArray(project.dos_name) &&
						project.dos_name.some(
							(name: string) => name.toLowerCase() === this.serviceName.toLowerCase(),
						),
				);

				// Only 6 projects total
				const projects = (websiteProjects.length >= 6 ? websiteProjects : result).slice(0, 6);

				// 3 projects per row
				const topProjects = projects.slice(0, 3);
				const bottomProjects = projects.slice(3, 6);

				// Show every project_images item separately
				this.marqueeRowTop = this.getProjectImages(topProjects);
				this.marqueeRowBottom = this.getProjectImages(bottomProjects);

				this.cdr.markForCheck();

				if (this.isBrowser) {
					this.ngZone.runOutsideAngular(() => {
						requestAnimationFrame(() => this.setupCardHoverButtons());
					});
				}
			}
		});
	}

	getProjectImages(projects: any[]): any[] {
		return projects.flatMap((project) => {
			const images = project.project_images || [];

			return images.map((image: any) => ({
				...project,
				marqueeImage: image,
			}));
		});
	}
	getProjectLink(project: any): string | null {
		if (project.link && project.link !== '#') {
			return project.link;
		}
		if (project.url_key && project.url_key !== '#') {
			return this.translationService.localizedPath('/project-details/' + project.url_key);
		}
		return null;
	}

	isExternalLink(project: any): boolean {
		return !!(project.link && project.link !== '#');
	}

	projectName(project: any): string {
		return this.translationService.currentLang() === 'ar' ? project.name_ar : project.name;
	}

	private setupCardHoverButtons(): void {
		const frames = this.hostRef.nativeElement.querySelectorAll<HTMLElement>('.card-hover-frame');

		frames.forEach((frame) => {
			if (this.boundThumbs.has(frame)) return;
			this.boundThumbs.add(frame);

			const btn = frame.querySelector<HTMLElement>('.card-hover-btn');
			if (!btn) return;

			let targetX = 0;
			let targetY = 0;
			let currentX = 0;
			let currentY = 0;
			let rafId: number | null = null;

			const moveTo = (event: MouseEvent) => {
				const rect = frame.getBoundingClientRect();
				targetX = event.clientX - rect.left - btn.offsetWidth / 2;
				targetY = event.clientY - rect.top - btn.offsetHeight / 2;
			};

			const step = () => {
				currentX += (targetX - currentX) * 0.25;
				currentY += (targetY - currentY) * 0.25;
				btn.style.transform = `translate3d(${currentX}px, ${currentY}px, 0)`;
				rafId = requestAnimationFrame(step);
			};

			const handleMouseEnter = (event: MouseEvent): void => {
				frame.classList.add('is-hovering');
				moveTo(event);
				currentX = targetX;
				currentY = targetY;
				if (rafId === null) {
					rafId = requestAnimationFrame(step);
				}
			};

			const handleMouseLeave = (): void => {
				frame.classList.remove('is-hovering');
				if (rafId !== null) {
					cancelAnimationFrame(rafId);
					rafId = null;
				}
			};

			frame.addEventListener('mouseenter', handleMouseEnter);
			frame.addEventListener('mousemove', moveTo);
			frame.addEventListener('mouseleave', handleMouseLeave);

			this.cardHoverCleanups.push(() => {
				frame.removeEventListener('mouseenter', handleMouseEnter);
				frame.removeEventListener('mousemove', moveTo);
				frame.removeEventListener('mouseleave', handleMouseLeave);
				if (rafId !== null) {
					cancelAnimationFrame(rafId);
				}
			});
		});
	}
}
