import { CommonModule, isPlatformBrowser } from '@angular/common';
import {
	AfterViewInit,
	ChangeDetectionStrategy,
	Component,
	ElementRef,
	Inject,
	NgZone,
	OnDestroy,
	PLATFORM_ID,
	QueryList,
	Renderer2,
	ViewChild,
	ViewChildren,
	computed,
	effect,
	inject,
	input,
} from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { merge } from 'rxjs';
import { map } from 'rxjs/operators';

import { TranslationService } from '../../../core/services/translation.service';

/** Horizontal spacing (px) between two consecutive stages along the wave track. */
const STAGE_GAP = 650;

/** X offset (px) of the first stage's marker inside its slot — must match `.lyric-marker`'s `left`. */
const TRACK_START_OFFSET = 210;

/** Blank run-out (px) after the last marker so the wave doesn't stop dead on it. */
const TRACK_END_PADDING = 210;

/** Height (px) of the wave's SVG coordinate space. */
const WAVE_HEIGHT = 320;

/** Marker heights (px) on the wave, cycled so any number of stages keeps the same rhythm. */
const STAGE_WAVE_POINTS = [180, 220, 170, 190, 170];

/** Crest between two consecutive markers: x offset from the left marker and height on the wave, cycled. */
const WAVE_CRESTS = [
	{ x: 350, y: 80 },
	{ x: 390, y: 60 },
	{ x: 390, y: 50 },
	{ x: 440, y: 100 },
];

interface ServiceStage {
	key: string;
	number: string;
	/** Y position (px) of this stage's marker on the wave path. */
	wavePoint: number;
}

@Component({
	selector: 'app-service-stages',
	standalone: true,
	imports: [CommonModule, TranslateModule],
	templateUrl: './service-stages.component.html',
	styleUrl: './service-stages.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ServiceStagesComponent implements AfterViewInit, OnDestroy {
	readonly consultationLink = input('');
	readonly sectionKey = input('SERVICESTAGES.BRANDING');

	readonly stageGap = STAGE_GAP;

	private readonly translate = inject(TranslateService);

	/** Bumps whenever a translation file finishes loading or the language changes, so `stages` re-reads the JSON. */
	private readonly translationsVersion = toSignal(
		merge(this.translate.onLangChange, this.translate.onTranslationChange, this.translate.onFallbackLangChange).pipe(
			map((_, index) => index + 1),
		),
		{ initialValue: 0 },
	);

	/**
	 * One stage per entry under `<sectionKey>.LIST` in the active language's JSON, in file
	 * order — so a service with 3 or 6 stages renders 3 or 6 markers without touching code.
	 */
	readonly stages = computed<ServiceStage[]>(() => {
		this.translationsVersion();

		const list = this.translate.instant(`${this.sectionKey()}.LIST`);
		const keys = list && typeof list === 'object' ? Object.keys(list) : [];

		return keys.map((key, index) => ({
			key,
			number: String(index + 1),
			wavePoint: STAGE_WAVE_POINTS[index % STAGE_WAVE_POINTS.length],
		}));
	});

	readonly trackWidth = computed(
		() => TRACK_START_OFFSET + Math.max(this.stages().length - 1, 0) * STAGE_GAP + TRACK_END_PADDING,
	);

	readonly waveViewBox = computed(() => `0 0 ${this.trackWidth()} ${WAVE_HEIGHT}`);

	readonly wavePath = computed(() => buildWavePath(this.stages()));

	/** Marker-to-marker moves; `.lyrics-section` scales its scroll height by this via `--stage-transitions`. */
	readonly stageTransitions = computed(() => Math.max(this.stages().length - 1, 1));

	@ViewChild('lyricsSection') private sectionRef?: ElementRef<HTMLDivElement>;
	@ViewChild('lyricsPin') private pinRef?: ElementRef<HTMLDivElement>;
	@ViewChild('lyricsTrack') private trackRef?: ElementRef<HTMLDivElement>;
	@ViewChild('waveProgress') private progressRef?: ElementRef<SVGPathElement>;
	@ViewChildren('lyricStage') private stageRefs?: QueryList<ElementRef<HTMLDivElement>>;

	private readonly isBrowser: boolean;
	private intersectionObserver?: IntersectionObserver;
	private ticking = false;
	private rafId?: number;

	// Emulates GSAP ScrollTrigger's `pin: true` with plain JS, same approach as
	// ServicesScrollerComponent — this site's global `body { overflow-x: hidden }`
	// makes `body` a scroll container, which becomes the containing block for
	// `position: sticky` descendants instead of the viewport, so sticky never engages.
	private readonly applyScrollProgress = (): void => {
		const section = this.sectionRef?.nativeElement;
		const pin = this.pinRef?.nativeElement;
		const track = this.trackRef?.nativeElement;
		const progressPath = this.progressRef?.nativeElement;
		const stageElements = this.stageRefs?.toArray();
		const stageCount = this.stages().length;

		if (!section || !pin || !track || !progressPath || !stageElements?.length) {
			return;
		}

		const viewportHeight = window.innerHeight;
		const scrollable = section.offsetHeight - viewportHeight;

		if (scrollable <= 0) {
			return;
		}

		const rect = section.getBoundingClientRect();

		if (rect.top > 0) {
			this.renderer.setStyle(pin, 'position', 'relative');
			this.renderer.removeStyle(pin, 'top');
			this.renderer.removeStyle(pin, 'left');
			this.renderer.removeStyle(pin, 'width');
		} else if (rect.bottom <= viewportHeight) {
			this.renderer.setStyle(pin, 'position', 'absolute');
			this.renderer.setStyle(pin, 'top', `${scrollable}px`);
			this.renderer.setStyle(pin, 'left', '0px');
			this.renderer.setStyle(pin, 'width', '100%');
		} else {
			this.renderer.setStyle(pin, 'position', 'fixed');
			this.renderer.setStyle(pin, 'top', '0px');
			this.renderer.setStyle(pin, 'left', `${rect.left}px`);
			this.renderer.setStyle(pin, 'width', `${rect.width}px`);
		}

		const progress = clamp(-rect.top / scrollable, 0, 1);

		const totalDistance = (stageCount - 1) * STAGE_GAP;
		const translateX = window.innerWidth / 2 - TRACK_START_OFFSET - progress * totalDistance;

		this.renderer.setStyle(track, 'transform', `translate3d(${translateX}px, 0, 0)`);

		const pathLength = progressPath.getTotalLength();

		this.renderer.setStyle(progressPath, 'stroke-dasharray', `${pathLength}`);
		this.renderer.setStyle(progressPath, 'stroke-dashoffset', `${pathLength * (1 - progress)}`);

		const stagePosition = progress * (stageCount - 1);

		stageElements.forEach((ref, index) => {
			const element = ref.nativeElement;
			const distance = index - stagePosition;

			if (distance <= 0) {
				// Active and already-passed stages stay perfectly crisp.
				this.renderer.setStyle(element, 'transform', 'scale(1)');
				this.renderer.setStyle(element, 'filter', 'blur(0px)');
				this.renderer.setStyle(element, 'opacity', '1');
			} else {
				// Upcoming stages blur/shrink/fade proportionally to how far away they are.
				const blur = Math.min(distance * 5, 8);
				const opacity = Math.max(0.2, 1 - distance * 0.35);
				const scale = Math.max(0.8, 1 - distance * 0.08);

				this.renderer.setStyle(element, 'transform', `scale(${scale})`);
				this.renderer.setStyle(element, 'filter', `blur(${blur}px)`);
				this.renderer.setStyle(element, 'opacity', `${opacity}`);
			}

			this.renderer.setStyle(element, 'z-index', `${100 - Math.round(Math.abs(distance) * 10)}`);
		});
	};

	constructor(
		public translationService: TranslationService,
		private readonly hostRef: ElementRef<HTMLElement>,
		private readonly renderer: Renderer2,
		private readonly ngZone: NgZone,
		@Inject(PLATFORM_ID) platformId: Object,
	) {
		this.isBrowser = isPlatformBrowser(platformId);

		effect(() => {
			this.translationService.currentLang();
		});
	}

	ngAfterViewInit(): void {
		if (!this.isBrowser) {
			return;
		}

		this.ngZone.runOutsideAngular(() => {
			window.addEventListener('resize', this.applyScrollProgress);

			this.intersectionObserver = new IntersectionObserver(
				([entry]) => this.setTicking(entry.isIntersecting),
				{ rootMargin: '200px 0px' },
			);
			this.intersectionObserver.observe(this.hostRef.nativeElement);
		});

		this.applyScrollProgress();
	}

	ngOnDestroy(): void {
		if (!this.isBrowser) {
			return;
		}

		this.setTicking(false);
		this.intersectionObserver?.disconnect();
		window.removeEventListener('resize', this.applyScrollProgress);
	}

	private setTicking(active: boolean): void {
		if (active === this.ticking) {
			return;
		}

		this.ticking = active;

		if (!active) {
			if (this.rafId !== undefined) {
				cancelAnimationFrame(this.rafId);
				this.rafId = undefined;
			}

			return;
		}

		const step = () => {
			if (!this.ticking) {
				return;
			}

			this.applyScrollProgress();
			this.rafId = requestAnimationFrame(step);
		};

		this.rafId = requestAnimationFrame(step);
	}
}

function clamp(value: number, min: number, max: number): number {
	return Math.min(Math.max(value, min), max);
}

/** Track x (px) of the marker for the stage at `index`. */
function stageX(index: number): number {
	return TRACK_START_OFFSET + index * STAGE_GAP;
}

/** Cubic Bézier from (x0, y0) to (x1, y1) that leaves and arrives flat, so joins never kink. */
function flatCurve(x0: number, y0: number, x1: number, y1: number): string {
	const width = x1 - x0;

	return `C ${x0 + width * 0.4} ${y0} ${x1 - width * 0.3} ${y1} ${x1} ${y1}`;
}

/** Draws one crest between every pair of consecutive markers, passing exactly through each marker. */
function buildWavePath(stages: ServiceStage[]): string {
	if (!stages.length) {
		return '';
	}

	const segments = [`M ${stageX(0)} ${stages[0].wavePoint}`];

	for (let index = 0; index < stages.length - 1; index++) {
		const fromX = stageX(index);
		const toX = stageX(index + 1);
		const crest = WAVE_CRESTS[index % WAVE_CRESTS.length];
		const crestX = fromX + crest.x;

		segments.push(
			flatCurve(fromX, stages[index].wavePoint, crestX, crest.y),
			flatCurve(crestX, crest.y, toX, stages[index + 1].wavePoint),
		);
	}

	return segments.join(' ');
}
