import {
  Component,
  ChangeDetectionStrategy,
  Input,
  OnChanges,
  SimpleChanges,
  OnDestroy,
  ElementRef,
  ViewChild,
  Inject,
  PLATFORM_ID,
} from '@angular/core';
import { CommonModule, isPlatformBrowser } from '@angular/common';
import { environment } from '../../../../environments/environment';
import { LucideAngularModule } from 'lucide-angular';
import { TranslateModule } from '@ngx-translate/core';
import { TranslateFieldPipe } from '../../../shared/pipes/translate-field.pipe';
import { TranslationService } from '../../../core/services/translation.service';
import { Router } from '@angular/router';

@Component({
  selector: 'app-services-banner',
  standalone: true,
  imports: [CommonModule, LucideAngularModule, TranslateModule, TranslateFieldPipe],
  templateUrl: './services-banner.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
  styleUrl: './services-banner.component.scss',
})
export class ServicesBannerComponent implements OnChanges, OnDestroy {
  imgUrl: string = environment.baseUrl + '/public/banner/';
  baseUrl: string = environment.url;
  @Input() product: any[] = [];
  @Input() isDark: boolean = false;
  @Input() imagePosition: string = '';
  @Input() contentClass: string = '';
  @Input() videoUrl: string = '';

  @ViewChild('bannerVideo') bannerVideo?: ElementRef<HTMLVideoElement>;
  @ViewChild('videoFrame') videoFrame?: ElementRef<HTMLDivElement>;
  @ViewChild('videoHoverBtn') videoHoverBtn?: ElementRef<HTMLDivElement>;
  @ViewChild('videoHoverBtnInner') videoHoverBtnInner?: ElementRef<HTMLDivElement>;
  @ViewChild('videoModal') videoModal?: ElementRef<HTMLDivElement>;
  @ViewChild('modalVideo') modalVideo?: ElementRef<HTMLVideoElement>;

  private hoverBtnTargetX = 0;
  private hoverBtnTargetY = 0;
  private hoverBtnCurrentX = 0;
  private hoverBtnCurrentY = 0;
  private hoverBtnRafId: number | null = null;

  constructor(
    public translationService: TranslationService,
    public router: Router,
    @Inject(PLATFORM_ID) private platformId: Object,
  ) {}

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['product'] && this.product?.length) {
    }
  }

  ngOnDestroy(): void {
    if (this.hoverBtnRafId !== null) {
      cancelAnimationFrame(this.hoverBtnRafId);
      this.hoverBtnRafId = null;
    }
  }

  onVideoMouseMove(event: MouseEvent): void {
    const frame = this.videoFrame?.nativeElement;
    const btn = this.videoHoverBtn?.nativeElement;
    if (!frame || !btn) return;

    const rect = frame.getBoundingClientRect();
    this.hoverBtnTargetX = event.clientX - rect.left - btn.offsetWidth / 2;
    this.hoverBtnTargetY = event.clientY - rect.top - btn.offsetHeight / 2;
  }

  onVideoMouseEnter(event: MouseEvent): void {
    this.videoFrame?.nativeElement.classList.add('is-hovering');
    this.onVideoMouseMove(event);
    this.hoverBtnCurrentX = this.hoverBtnTargetX;
    this.hoverBtnCurrentY = this.hoverBtnTargetY;
    this.startHoverBtnLoop();
  }

  onVideoMouseLeave(): void {
    this.videoFrame?.nativeElement.classList.remove('is-hovering');
    if (this.hoverBtnRafId !== null) {
      cancelAnimationFrame(this.hoverBtnRafId);
      this.hoverBtnRafId = null;
    }
  }

  onHoverBtnAnimationEnd(): void {
    this.videoHoverBtnInner?.nativeElement.classList.remove('is-clicking');
  }

  private startHoverBtnLoop(): void {
    if (this.hoverBtnRafId !== null) return;

    const step = () => {
      this.hoverBtnCurrentX += (this.hoverBtnTargetX - this.hoverBtnCurrentX) * 0.25;
      this.hoverBtnCurrentY += (this.hoverBtnTargetY - this.hoverBtnCurrentY) * 0.25;
      const btn = this.videoHoverBtn?.nativeElement;
      if (btn) {
        btn.style.transform = `translate3d(${this.hoverBtnCurrentX}px, ${this.hoverBtnCurrentY}px, 0)`;
      }
      this.hoverBtnRafId = requestAnimationFrame(step);
    };

    this.hoverBtnRafId = requestAnimationFrame(step);
  }

  playVideoInModal(): void {
    if (!isPlatformBrowser(this.platformId)) return;

    const bgVideo = this.bannerVideo?.nativeElement;
    const modalVideo = this.modalVideo?.nativeElement;
    const modal = this.videoModal?.nativeElement;
    if (!bgVideo || !modalVideo || !modal) return;

    const inner = this.videoHoverBtnInner?.nativeElement;
    if (inner) {
      this.videoFrame?.nativeElement.classList.remove('is-hovering');
      inner.classList.remove('is-clicking');
      void inner.offsetWidth;
      inner.classList.add('is-clicking');
    }

    bgVideo.pause();
    modal.classList.add('is-open');

    modalVideo.muted = false;
    modalVideo.volume = 1;
    modalVideo.currentTime = 0;
    modalVideo.setAttribute('controls', '');
    modalVideo.play().catch(() => {});
  }

  closeVideoModal(): void {
    if (!isPlatformBrowser(this.platformId)) return;

    const bgVideo = this.bannerVideo?.nativeElement;
    const modalVideo = this.modalVideo?.nativeElement;
    const modal = this.videoModal?.nativeElement;
    if (!modal) return;

    modalVideo?.pause();
    if (modalVideo) modalVideo.currentTime = 0;
    modal.classList.remove('is-open');

    bgVideo?.play().catch(() => {});
  }
}
